import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_COMANDA, MODELO_CAFETERIA, TABLA_COMANDAS } from '../../models/cafeteria-comanda.model.mjs';

export async function buscarCafeteriaRepository(cafeteriaId) {
  const { Item } = await MODELO_CAFETERIA.build(GetItemCommand)
    .key({ cafeteriaId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarCafeteriaRepository(cafeteriaId, minimo) {
  const { Items = [] } = await TABLA_COMANDAS.build(QueryCommand)
    .entities(MODELO_COMANDA)
    .query({ index: 'PorCafeteria', partition: cafeteriaId })
    .options({ filters: { Comanda: { attr: 'importeCentimos', gte: minimo } } })
    .send();
  return Items;
}
